  u64arr rsegs m' (RCTX + 80) (actives st') /\ u64arr rsegs m' (RCTX + 464) (usages st')
  /\ u8arr rsegs m' (RCTX + 848) (unmap_seqs st') /\ u8arr rsegs m' (RCTX + 880) (bouncess st').
